// Sprite atlases generated by `pnpm sprites` (tools/build-sprites.ts → public/atlases/<name>.png|json,
// Pixi Spritesheet format, frames `<entity>/<anim>/<nn>`). Loaded before the first frame, so
// `body[data-ready]` implies every atlas is on the GPU-ready path.
import { Assets, type Spritesheet, type Texture } from 'pixi.js';

export const ATLAS_NAMES = ['debug'] as const;
export type AtlasName = (typeof ATLAS_NAMES)[number];
export type Atlases = Readonly<Record<AtlasName, Spritesheet>>;

let configured = false;

export async function loadAtlases(): Promise<Atlases> {
  if (!configured) {
    // CSP (M0-12): Pixi's default image loader runs in a Worker built from a blob: URL, which a strict
    // `script-src 'self'` blocks. Decode on the main thread instead (fetch + createImageBitmap).
    Assets.setPreferences({ preferWorkers: false });
    configured = true;
  }
  const sheets = await Promise.all(
    ATLAS_NAMES.map((name) => Assets.load<Spritesheet>(`${import.meta.env.BASE_URL}atlases/${name}.json`)),
  );
  return Object.fromEntries(ATLAS_NAMES.map((name, i) => [name, sheets[i]])) as Atlases;
}

/** Frame texture by name; a missing frame is a build/content bug, so it throws. */
export function frame(atlases: Atlases, atlas: AtlasName, name: string): Texture {
  const texture = atlases[atlas].textures[name];
  if (!texture) throw new Error(`atlas "${atlas}" has no frame "${name}" — run \`pnpm sprites\``);
  return texture;
}
